  "ex-market-p": "40,000 AEQ of purchases every month, but 200,000 AEQ stay in the account. Free up to 60,000 (1.5 months' turnover), 0.5 % on the next 60,000 up to 3 months' turnover, 2 % on the 80,000 above. A normal reserve of two months would cost only 100 AEQ a month.",
