  "ex-hoard-p": "As a person: impossible, the limit is 25,000 AEQ. On 100 other addresses of 1,000 AEQ: 1 % a month = 1,000 AEQ a month. As a “business” without turnover: 98,000 × 2 % = 1,960 AEQ a month.",
  "ex-hoard-r": "Hoarding pays off in no form (about 24 % a year)",
  "age-h": "What counts as turnover?",
