  "fb-sub": "Jeder verifizierte Mensch bekommt täglich ein Grundeinkommen und sucht Orte, an denen er es ausgeben kann. Unternehmen, die AEQ annehmen, gewinnen diese Kundschaft, zahlen pro Zahlung nichts und geben das Geld als Löhne und Einkäufe weiter.",
  "fb-ex-label": "Beispiel",
  "fb-btn": "Alles für Unternehmen →",
  "fb-btn2": "So machen Sie mit",
  "fp-h2": "Ihr fairer Anteil, jeden Tag",
  "fp-sub": "Jeder verifizierte Mensch erhält einmalig 1.000 AEQ und danach jeden Tag einen gleichen Anteil an allem, was das Netz einnimmt.",
  "fp-btn": "Alle sechs Zusagen, das Grundeinkommen und Beispiele →",
  "st-h2": "Phase 1: ein öffentlicher Test",
  "st-p": "Aequitas läuft, ist aber nicht fertig. AEQ lässt sich nur in die Testwährung tUSD tauschen, die rechtliche Prüfung nach der EU-Kryptoverordnung steht noch aus, und die Gesichtsprüfung hat benannte Grenzen. Die Wirtschaftsregeln gelten ab 1. Oktober 2026.",
  "st-link": "Fahrplan und was noch offen ist →",
  "pg-ppl-h1": "Für Menschen",
  "pg-ppl-sub": "Was Aequitas jedem Menschen zusagt, wie das tägliche Grundeinkommen funktioniert und was Sie zahlen, mit Rechenbeispielen.",
