  "jn-h2": "In vier Schritten zur ersten Zahlung",
  "jn-sub": "Was eine Bäckerei, ein Café oder eine Werkstatt braucht, um AEQ anzunehmen.",
  "jn-1-h": "Unternehmenskonto eröffnen",
  "jn-1-p": "Ein verifizierter Mensch und die Firmen-Wallet unterschreiben gemeinsam. Bis zu 10 Verantwortliche pro Unternehmen, höchstens 3 Unternehmen pro Mensch. Kein Amt, keine Prüfstelle.",
  "jn-3-h": "Weitergeben",
  "jn-3-p": "Löhne an Menschen kosten nichts, Zahlungen an Lieferanten 0,1 %. Bis zu anderthalb Monatsumsätze zahlen nie eine Abgabe.",
