  "ex-ben-h": "Ben trabaja en un café",
  "ex-ben-p": "Gana 2.000 AEQ de salario, gasta 1.500 AEQ y cambia 1.000 AEQ a euros para el alquiler. Comisión sobre los 500 AEQ por encima de su importe libre: 0,5 AEQ. Comisión normal de cambio: 1 AEQ. Sin gravamen de salida: hasta 3.000 AEQ al mes son libres.",
