  "hero-sub": "Каждый проверенный человек получает 1 000 AEQ и ежедневный базовый доход. Бизнес принимает оплату без комиссий за карты и платит зарплаты бесплатно.",
  "btn-register": "Зарегистрироваться",
  "stat-humans-lbl": "Подтверждённые люди",
  "stat-supply-lbl": "AEQ в обращении",
  "stat-gini-lbl": "Gini",
