  "cmp-r3-p": "0,5 % в месяц, только сверх 5 000 AEQ",
  "cmp-r3-b": "до 1,5 месячного оборота бесплатно, затем 0,5 % в месяц; сверх 3 месячных оборотов 2 %",
  "cmp-r3-f": "1 % в месяц",
  "cmp-r4": "Переводы",
  "cmp-r4-p": "первые 1 000 AEQ в месяц бесплатно, затем 0,1 %",
  "cmp-r4-b": "людям бесплатно, иначе 0,1 %",
  "cmp-r4-f": "0,1 %",
  "cmp-r5": "Обмен на евро или доллары",
  "cmp-r5-p": "3 000 AEQ в месяц бесплатно, затем 2 %",
