  "cmp-r6-p": "каждый проверенный человек, один раз",
  "cmp-r6-b": "от одного до десяти проверенных людей; не более 3 на человека",
  "cmp-r6-f": "кто угодно",
  "cmp-note": "Эти правила действуют с 1 октября 2026 года. Каждый сбор идёт на 100 % в базовый доход.",
  "ppl-label": "Для людей",
  "ppl-h2": "Шесть обещаний каждому человеку",
  "ppl-sub": "Самые справедливые деньги должны сначала казаться справедливыми тому, у кого мало.",
  "ppl-1": "<strong>Ваша справедливая доля неприкосновенна.</strong> С первых 1 000 AEQ никогда не берётся сбор.",
  "ppl-2": "<strong>Повседневная жизнь ничего не стоит.</strong> Первые 1 000 AEQ, которые вы тратите в месяц, без комиссии.",
  "ppl-3": "<strong>Зарплата есть зарплата.</strong> До 3 000 AEQ в месяц обмениваются на евро или доллары без сбора, откуда бы ни пришли деньги.",
  "ppl-4": "<strong>Копить можно.</strong> До 5 000 AEQ ваши сбережения ничего не теряют.",
  "ppl-5": "<strong>У кого больше, тот вносит больше.</strong> Сбережения сверх 5 000 AEQ платят 0,5 % в месяц; предел 25 000 AEQ остаётся.",
  "ppl-6": "<strong>Люди всегда платят за хранение и выход меньше, чем компании,</strong> и всё, что кто-либо платит, возвращается всем людям поровну.",
  "biz-label": "Для бизнеса",
  "biz-h2": "Принимайте AEQ, передавайте дальше, ничего не платите",
  "biz-sub": "Компании могут принимать, хранить и тратить AEQ. Правила заставляют деньги проходить через них и возвращаться к людям: простой денег стоит дорого, передача дальше бесплатна.",
  "biz-b1-h": "Без комиссий за карты",
  "biz-b1-p": "Платёж ничего не стоит компании. Покупатели тратят первые 1 000 AEQ в месяц без комиссии.",
  "biz-b2-h": "Зарплата без комиссий",
  "biz-b2-p": "Зарплаты в AEQ ничего не стоят. Каждый человек может обменять до 3 000 AEQ в месяц на евро или доллары без сбора.",
  "biz-b3-h": "Без потолка роста",
  "biz-b3-p": "Люди могут держать не более 25 000 AEQ, у бизнеса нет фиксированного предела. До полутора месячных оборотов никогда ничего не стоят.",
  "biz-b4-h": "Оплата за секунды",
  "biz-b4-p": "Деньги приходят за секунды. Без возвратов платежей и ожидания расчётов.",
  "biz-r1-k": "Лежащие деньги",
  "biz-r1-v": "До 1,5 месячного оборота (не меньше 2 000 AEQ): бесплатно · до 3 месячных оборотов: 0,5 % в месяц на часть сверх · выше: 2 % в месяц",
  "biz-r2-k": "Что считается оборотом",
  "biz-r2-v": "Среднее за последние 90 дней. Покупки учитываются до 1 000 AEQ на человека в месяц; между компаниями учитывается только превышение; зарплаты, собственные взносы и обмен в AEQ не учитываются.",
  "biz-r3-k": "Выход в евро или доллары",
  "biz-r3-v": "Сбор 2 %. Люди: 3 000 AEQ в месяц бесплатно",
