  "step3-h": "领取",
  "step3-p": "每次成功注册获得一次 1,000 AEQ。",
  "sybil-blurb": "<strong>Sybil / 防护：</strong>实时人脸核验（两家独立比对服务的法定多数）+ 签名证明 + 链上 nullifier，仅可使用一次。明示的限制：人脸核验启用前（2026-08-25，今日 18 个账户中的几乎全部）注册的账户没有人脸模板；比对阈值尚未用真实采集校准；活体检测为转头指令，高级深度伪造仍是残余风险；分片模式（<code>MPC</code>）处于影子运行，每家服务仍持有完整的加密模板。",
  "how-link": "立即注册并领取你的 1,000 AEQ →",
  "why-label": "公平",
  "why-h2": "比特币基尼系数约 0.85 — 高于任何国家",
  "why-sub": "供应量 = 已验证人数 × 1,000 AEQ。Gini 来自实时节点。Go L1 是账本真相来源（不仅是镜像合约）。",
  "why-link": "洛伦兹曲线、历史记录与各国对比 →",
  "disc-title": "Phase 1 声明",
  "disc-body": "Phase 1：自 2026-08-25 起，证明服务器拒绝任何没有比对法定多数签名证明的注册 — 换一部手机不再能让同一张脸获得第二个账户。尚未成立的部分：该日期之前注册的账户没有人脸模板，原则上可以用新钱包再次注册；错误率尚未校准（需要约 1,000 组冒名配对）；活体检测为转头指令，更强的深度伪造防御正在校准中。请将「一人一账户」理解为「已核验、并明示限制」，而非「无法绕过」。",
  "oss-line": "<strong>开源：</strong>核心链公开 · 身份/证明服务在 Phase 1 部分私有。",
