  "lh-sub": "去中心化网络无法核实一个账户背后是否有真实公司，也不应该去核实：没有商业登记，没有官方机构，没有把关人。取而代之的是：任何形式的囤积都昂贵，任何形式的传递都便宜。只有资金真正流动的人，注册为企业才划算。",
  "lh-list-h": "我们找到的所有绕行办法，以及它们为何行不通",
  "lh-1": "<strong>注册成企业来绕过 25,000 的上限。</strong> 没有真实营业额的企业，对超过 2,000 AEQ 的全部余额每月支付 2 %，是个人的四倍。",
  "lh-2": "<strong>在自己或友好的公司之间兜圈转钱来虚增营业额。</strong> 企业之间只计净额，自己的公司彼此不计入：兜圈毫无收获。",
  "lh-3": "<strong>自己或通过店主往里打钱。</strong> 企业自身负责人的付款不算营业额。",
  "lh-4": "<strong>朋友来消费再把钱拿回去。</strong> 每人每月对每家企业最多计入 1,000 AEQ。要保护 150,000 AEQ，每个月都需要 100 个真人，而且公开可见。",
  "lh-5": "<strong>成立很多公司以获得很多免费额度。</strong>每人最多 3 个企业账户，所以最多 6,000 AEQ 免费。",
  "lh-6": "<strong>把自己当作“员工”付薪。</strong>付给负责人的款项算作提取，不算工资。",
  "lh-7": "<strong>给朋友发假工资，让他们兑换后退回现金。</strong> 每人每月只有 3,000 AEQ 以内的兑换免退出费，而且工资总额公开。",
  "lh-8": "<strong>把钱停放在流动性池里。</strong> 只有个人才能提供流动性。",
  "lh-9": "<strong>用智能合约藏钱。</strong>合约属于其他地址：最多 1,000 AEQ，每月 1%。",
  "lh-honest": "<strong>老实说还剩下什么：</strong>世界上没有任何货币体系能阻止许多真实的人串通。在这里，每一种已知的串通都得不偿失，或者只限于小额。企业营业额和工资总额是公开的，异常模式会显现出来。谁发现新漏洞就报告，规则随之调整。",
  "rm-label": "路线图",
  "rm-h2": "接下来",
  "rm-1-h": "现在：第 1 阶段",
  "rm-1-p": "注册时由两个独立比对服务进行实时人脸检查。起步 1,000 AEQ，每天发放基本收入。",
  "rm-2-h": "2026 年 10 月 1 日",
  "rm-2-p": "经济规则生效：三种账户类型、闲置资金费、退出费、个人每月免费额度。",
  "rm-3-h": "商店应用",
  "rm-3-p": "带二维码的收银模式和会计导出。",
  "rm-4-h": "试点城市",
  "rm-4-p": "5–10 家商店（咖啡馆、面包店、农场店、理发店、修理铺），为期三个月。衡量：多少留在流通中，多少流出，多少进入基本收入。",
  "rm-5-h": "法律审查和真正的稳定币",
  "rm-5-p": "在使用真钱之前：依据欧盟加密资产条例（MiCA）进行审查，并用受监管的欧元稳定币取代测试货币 tUSD。之后才会更广泛开放。",
  "op-label": "坦白说",
  "op-h2": "尚未完成的部分",
  "op-1": "<strong>只有测试货币。</strong>目前只能兑换成 tUSD；还没有真正兑换成欧元或美元的出口。",
  "op-2": "<strong>法律审查尚待进行。</strong>AEQ 和内置兑换是否属于欧盟 MiCA 条例，必须在使用真钱之前审查。",
  "op-3": "<strong>汇率风险。</strong>在 AEQ 规模尚小时，价格会波动。对谨慎的商店来说，立即兑换就是答案。",
  "op-4": "<strong>税务。</strong>对企业而言，AEQ 收入按付款当日的欧元价值计入营业收入。",
  "op-5": "<strong>这些数字是起始值。</strong> 2,000 AEQ 基础额、1.5 和 3 个月营业额、0.5 %/2 %、2 %、每月 1,000 和 3,000：在试点城市测量后再调整。",
  "faq-label": "问题",
  "faq-h2": "常见问题",
  "faq-q1": "为什么企业不干脆只收美元？",
  "faq-a1": "那样每次购物都是在卖出 AEQ。几乎不会有买家，价格以及基本收入会不断下跌。只有企业能自己把 AEQ 传递出去——给员工、供应商和其他企业——流通才会产生。",
  "faq-q2": "2026 年 10 月 1 日对我个人有什么变化？",
  "faq-a2": "对大多数人没有变化，或者更便宜：你每月花的前 1,000 AEQ 免手续费，闲置资金费只对超过 5,000 AEQ 的部分收取。",
  "faq-q3": "有东西被销毁吗？",
  "faq-a3": "没有。每笔手续费和每项费用都 100% 进入基本收入，并平均回到所有已验证的人手中。",
  "faq-q4": "企业能领取基本收入或投票吗？",
  "faq-a4": "不能。基本收入、投票权和公平份额只属于已验证的人。每个企业账户背后都有一到十位对其负责的已验证的人。",
  "faq-q5": "什么是“其他地址”？",
  "faq-a5": "既不是已验证个人也不是企业的任何地址：访客的钱包、小费罐、简单的合约。最多持有 1,000 AEQ，每月支付 1%。",
  "faq-q6": "为什么按人设定的规则在这里行得通？",
  "faq-a6": "每个人在 Aequitas 中只存在一次。按人计算的免费额度无法通过更多账户成倍增加。其他任何货币都做不到。",
  "faq-q7": "这样的钱以前成功过吗？",
  "faq-a7": "成功过。沃尔格尔（奥地利，1932 年）的货币每月贬值 1%；它流通得如此之快，镇上用它修建了道路和桥梁，直到国家银行将其禁止。基姆高尔币（巴伐利亚，自 2003 年）有流通费并有数百家商店参与。WIR 银行（瑞士，自 1934 年）经营企业之间的结算货币。",
  "pg-eco-h1": "运作方式",
  "pg-eco-sub": "一个循环、三种账户、一套规则，以及货币为何保持公平。",
  "pg-biz-h1": "面向企业的 Aequitas",
  "pg-biz-sub": "收款无刷卡手续费，发薪免费，让钱流动起来。只有闲置的钱才需付费。",
  "pg-road-h1": "路线图与问题",
  "pg-road-sub": "Aequitas 目前进展如何、接下来做什么，以及坦白说仍未解决的问题。",
  "pg-back": "← 返回概览",
  "fs-note": "<strong>每个上限都是公平份额的倍数。</strong>平均每人持有 1,000 AEQ，因为货币总量始终是人数 × 1,000 AEQ。所以 2,000 = 2×、3,000 = 3×、5,000 = 5×、25,000 = 25× 公平份额。上限不与美元挂钩：AEQ 升值或贬值时，每个人的公平份额随之变化，上限的含义保持不变。",
  "faq-q8": "为什么上限不与美元挂钩？",
  "faq-a8": "因为公平关乎每个人在全部货币中所占的份额，而不是美元金额。普通人始终持有恰好一份公平份额（1,000 AEQ），每个上限都是它的倍数。与美元挂钩需要一个有人能操纵的价格来源，而价格上涨会悄悄收紧上限。只有每月免费额度取决于生活中有多少用 AEQ 支付：试点城市之后，每月免手续费额度和兑换免费额度将跟随中位数人群每月的实际支出，但绝不低于 1 倍公平份额。",
