  "hero-sub": "Doğrulanmış her insan 1.000 AEQ ve her gün temel gelir alır. İşletmeler kart komisyonu olmadan tahsilat yapar ve maaşları ücretsiz öder.",
  "btn-register": "Hemen kaydolun",
