  "eco-p1-p": "Doğrulanmış her insan bir kez 1.000 AEQ alır. Başka kimse para yaratmaz: ne işletmeler, ne doğrulayıcılar, ne kurucular.",
  "eco-p2-h": "Dolaşım ödüllendirilir",
  "eco-p2-p": "Alışveriş yapmak, maaş ve tedarikçi ödemek çok az ya da hiç maliyet getirmez. Açık sınırların ötesinde bekleyen para küçük bir aylık kesinti öder.",
