  "fee-r4-v": "%0,1",
  "fee-note": "Ücret üstüne eklenir: alıcı her zaman tam tutarı alır, yani 10 AEQ'luk bir fiyat dükkâna tam 10 AEQ getirir. Büyük bakiyeler için ek ücret yoktur: servet zaten 25.000 AEQ sınırı ve 5.000 AEQ üzerindeki birikim kesintisiyle sınırlıdır. Bu kurallar 1 Ekim 2026'dan itibaren geçerlidir.",
