  "age-note": "Ciro, son 90 günün ortalamasıdır. Fazla kuralı döngüleri durdurur: üç firma birbirine para gönderirse her birinin girişi çıkışı kadar olur ve ücretsiz tutar büyümez. Bir işletmenin ilk 30 gününde bekleyen para kesintisi yoktur.",
