  "cmp-r3-p": "0,5 % ao mês, só acima de 5.000 AEQ",
  "cmp-r3-b": "até 1,5 mês de faturação livre, depois 0,5 % ao mês; acima de 3 meses de faturação 2 %",
  "cmp-r3-f": "1 % ao mês",
