  "cmp-r5-p": "3.000 AEQ por mês livres, depois 2 %",
  "cmp-r5-b": "2 %",
  "cmp-r6": "Quem abre",
  "cmp-r6-p": "cada pessoa verificada, uma vez",
  "cmp-r6-b": "de uma a dez pessoas verificadas; no máximo 3 por pessoa",
  "cmp-r6-f": "qualquer um",
  "cmp-note": "Estas regras valem a partir de 1º de outubro de 2026. Cada encargo vai 100 % para a renda básica.",
  "ppl-label": "Para as pessoas",
  "ppl-h2": "Seis promessas a cada pessoa",
  "ppl-sub": "O dinheiro mais justo tem de parecer justo primeiro para quem tem pouco.",
  "ppl-1": "<strong>Sua parte justa é intocável.</strong> Os primeiros 1.000 AEQ nunca pagam encargo.",
  "ppl-2": "<strong>O dia a dia não custa nada.</strong> Os primeiros 1.000 AEQ que você gasta por mês são livres de taxa.",
  "ppl-3": "<strong>Salário é salário.</strong> Até 3.000 AEQ por mês trocam-se em euros ou dólares sem taxa, venha o dinheiro de onde vier.",
  "ppl-4": "<strong>Poupar é permitido.</strong> Até 5.000 AEQ sua poupança não perde nada.",
  "ppl-5": "<strong>Quem tem mais contribui mais.</strong> A poupança acima de 5.000 AEQ paga 0,5 % ao mês; o limite de 25.000 AEQ mantém-se.",
  "ppl-6": "<strong>As pessoas sempre pagam menos que as empresas</strong> para guardar e sair, e tudo o que alguém paga volta igualmente para todas as pessoas.",
  "biz-label": "Para empresas",
  "biz-h2": "Aceite AEQ, passe adiante, não pague nada",
  "biz-sub": "As empresas podem aceitar, guardar e gastar AEQ. As regras fazem o dinheiro passar por elas e voltar às pessoas: deixá-lo parado custa, passá-lo adiante é grátis.",
  "biz-b1-h": "Sem taxas de cartão",
  "biz-b1-p": "Um pagamento não custa nada à empresa. Os clientes gastam os primeiros 1.000 AEQ por mês sem taxa.",
  "biz-b2-h": "Salários sem taxa",
  "biz-b2-p": "Os salários em AEQ não custam nada. Cada pessoa pode trocar até 3.000 AEQ por mês em euros ou dólares sem taxa.",
  "biz-b3-h": "Sem teto de crescimento",
  "biz-b3-p": "As pessoas podem ter no máximo 25.000 AEQ; as empresas não têm limite fixo. Até mês e meio de faturação nunca custa nada.",
  "biz-b4-h": "Pago em segundos",
  "biz-b4-p": "O dinheiro chega em segundos. Sem estornos, sem esperar pela liquidação.",
  "biz-r1-k": "Dinheiro parado",
  "biz-r1-v": "Até 1,5 mês de faturação (mínimo 2.000 AEQ): livre · até 3 meses de faturação: 0,5 % ao mês sobre a parte acima · para além disso: 2 % ao mês",
  "biz-r2-k": "O que conta como faturação",
  "biz-r2-v": "A média dos últimos 90 dias. As compras contam até 1.000 AEQ por pessoa e mês; entre empresas só conta o excedente; salários, entradas próprias e a troca para AEQ não contam.",
  "biz-r3-k": "Saída para euro ou dólar",
  "biz-r3-v": "Taxa de 2 %. Pessoas: 3.000 AEQ por mês livres",
  "biz-r4-k": "Entre empresas",
  "biz-r4-v": "0,1 %",
  "biz-r5-k": "Para onde vai",
  "biz-r5-v": "Cada encargo vai 100 % para a renda básica, igualmente para cada pessoa",
  "biz-live-from": "Regras valem a partir de",
  "biz-live-count": "Empresas registradas",
  "biz-link": "Ler o conceito completo →",
  "toc-label": "Nesta página",
  "toc-eco": "Economia",
  "toc-ubi": "Renda básica",
  "toc-cmp": "Tipos de conta",
