  "fee-r4-v": "0.1 %",
  "fee-note": "शुल्क ऊपर से जुड़ता है: पाने वाले को हमेशा पूरी रकम मिलती है, इसलिए 10 AEQ की क़ीमत दुकान को ठीक 10 AEQ देती है। बड़े बैलेंस पर कोई अतिरिक्त शुल्क नहीं: संपत्ति पहले से 25,000 AEQ की सीमा और 5,000 AEQ से ऊपर की बचत पर शुल्क से सीमित है। ये नियम 1 अक्टूबर 2026 से लागू हैं।",
