  "ex-anna-p": "उसके पास 1,200 AEQ हैं और वह हर महीने 800 AEQ खर्च करती है। कोई शुल्क नहीं (महीने में 1,000 से कम), कोई कटौती नहीं (5,000 से कम), कोई निकासी कटौती नहीं।",
  "ex-anna-r": "महीने में 0 AEQ देती है",
  "ex-ben-h": "बेन एक कैफ़े में काम करता है",
  "ex-ben-p": "वह 2,000 AEQ वेतन कमाता है, 1,500 AEQ ख़र्च करता है और किराए के लिए 1,000 AEQ यूरो में बदलता है। मुफ़्त सीमा से ऊपर के 500 AEQ पर शुल्क: 0.5 AEQ। सामान्य विनिमय शुल्क: 1 AEQ। कोई निकासी शुल्क नहीं: हर महीने 3,000 AEQ तक मुफ़्त।",
