  "ex-clara-h": "क्लारा के पास 20,000 AEQ हैं",
  "ex-clara-p": "वह हर महीने 3,000 AEQ ख़र्च करती है और 5,000 AEQ बदलती है। ट्रांसफ़र: 2,000 × 0.1 % = 2 AEQ। रुका हुआ पैसा: 15,000 × 0.5 % = 75 AEQ। विनिमय: 2,000 × 2 % = 40 AEQ (पहले 3,000 मुफ़्त)। सब कुछ बुनियादी आय में जाता है, यानी अन्ना और बेन को भी।",
