  "ex-cafe-h": "एक कैफ़े",
  "ex-cafe-p": "यह हर महीने 3,000 AEQ कमाता है और 1,500 वेतन, 800 आपूर्तिकर्ता को और 600 मालकिन को देता है। यह डेढ़ महीने के कारोबार से काफ़ी कम रखता है, इसलिए कोई रुके पैसे का शुल्क नहीं। सिर्फ़ आपूर्तिकर्ता को भुगतान पर 0.1 %।",
  "ex-cafe-r": "महीने में 0.8 AEQ देता है",
  "ex-market-h": "एक सुपरमार्केट जो जमा करता है",
  "ex-market-p": "हर महीने 40,000 AEQ की ख़रीद, लेकिन खाते में 200,000 AEQ पड़े रहते हैं। 60,000 (1.5 महीने का कारोबार) तक मुफ़्त, 3 महीने तक के अगले 60,000 पर 0.5 %, ऊपर के 80,000 पर 2 %। दो महीने का सामान्य रिज़र्व हर महीने सिर्फ़ 100 AEQ का पड़ता।",
  "ex-market-r": "हर महीने 1,900 AEQ बुनियादी आय में देता है",
